@startuml

class Airline {
  + Name : string
}

class Contract {
  + DeliveryConditions : string
  + LegalAspects : string
}

class Acquisition {
  + Model : string
  + Price : double
  + Options : string
  + DeliveryDate : date
}

class Employee {
  + Name : string
  + EmployeeID : int
}

class Salesperson {
  + SalespersonID : int
}

class Airplane {
  + SerialNumber : string
  + ModelType : string
}

Salesperson --|> Employee
Salesperson "1" -- "*" Contract : manages
Contract "1" -- "1..*" Acquisition
Acquisition "1" -- "1" Airplane
Airline "1" -- "*" Contract
Airline "0..1" o-- "0..*" Airline : daughterOf

@enduml

